@startuml

class Person {}

class Student extends Person {
  + name : string
  + email : string
}

class Tutor extends Person {
  + name : string
  + email : string
  + bank_account : string
}

class Subject {
  + name : string
}

class ExpertiseLevel {
  + level : string
}

class TutoringOffer {
  + expertise_level : ExpertiseLevel
  + hourly_price : float
}

class Availability {
  + day : string
  + start_time : time
  + end_time : time
}

class TutoringRequest {
  + requested_level : ExpertiseLevel
  + target_date : date
  + target_time : time
}

class TutoringSession {
  + actual_date : date
  + actual_time : time
  + status : string
}

class Payment {
  + amount : float
  + method : string
}

class Award {
  + month : string
}

Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringRequest : receives
Tutor "1" -- "*" TutoringSession : conducts
Tutor "1" -- "*" Award : receives
Student "1" -- "*" TutoringRequest : makes
Student "1" -- "*" TutoringSession : attends
Student "1" -- "*" Payment : makes
TutoringOffer "*" -- "1" Subject : in
TutoringOffer "*" -- "1" ExpertiseLevel : at
TutoringRequest "*" -- "1" Subject : for
TutoringRequest "*" -- "1" TutoringOffer : based_on
TutoringSession "*" -- "1" TutoringRequest : fulfills
TutoringSession "*" -- "1" TutoringSession : follows_up
TutoringSession "1" -- "1" Payment : results_in
TutoringSession "*" -- "1" Subject : in
Award "*" -- "1" Subject : for

@enduml

